mapper.select:
SELECT m.id AS merchant_id, m.name AS merchant_name, m.category,
       m.latitude, m.longitude
  FROM merchants m
 WHERE m.id = #{merchantId}
   AND m.region_id = #{regionId}
   AND m.category = 'OFFICE'

SELECT 
  FROM recommendation_requests rr
  LEFT JOIN merchants m ON m.id = rr.reference_merchant_id
  LEFT JOIN merchants sm ON sm.id = rr.secondary_reference_merchant_id
 WHERE rr.id = #{requestId}
   AND rr.user_id = #{userId}

SELECT FROM recommendation_requests rr LEFT JOIN merchants m ON m.id = rr.reference_merchant_id LEFT JOIN merchants sm ON sm.id = rr.secondary_reference_merchant_id WHERE rr.user_id = #{userId} AND rr.recommendation_type = 'ACCOMMODATION'
AND rr.reference_merchant_id = #{referenceMerchantId}
ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1

SELECT 
  FROM recommendation_requests rr
  LEFT JOIN merchants m ON m.id = rr.reference_merchant_id
  LEFT JOIN merchants sm ON sm.id = rr.secondary_reference_merchant_id
 WHERE rr.user_id = #{userId}
   AND rr.recommendation_type = 'RESTAURANT'
   AND rr.meal_type = #{mealType}

   AND rr.reference_merchant_id = #{referenceMerchantId}

 ORDER BY rr.created_at DESC, rr.id DESC LIMIT 1

SELECT result.id AS recommendation_result_id, result.recommendation_request_id, result.merchant_id, result.price_score, result.accessibility_score, result.rating_score, result.total_score, result.ranking, result.distance, m.name AS merchant_name, m.address, m.thumbnail_url, m.price, m.rating, EXISTS (SELECT 1 FROM bookmarks b WHERE b.users_id = (SELECT user_id FROM recommendation_requests WHERE id = #{requestId}) AND b.merchants_id = m.id AND b.is_deleted IS NULL) AS bookmarked FROM recommendation_results result JOIN merchants m ON m.id = result.merchant_id WHERE result.recommendation_request_id = #{requestId}
AND (result.ranking > #{cursorRanking} OR (result.ranking = #{cursorRanking} AND result.id > #{cursorId}))
ORDER BY result.ranking ASC, result.id ASC LIMIT #{limit}
